CREATE FUNCTION public.validate_animal_health() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(new.condition))=0 OR length(new.condition)>200 THEN RAISE EXCEPTION 'Enter a health condition (up to 200 characters)'; END IF; IF new.status NOT IN ('Healthy','Monitoring','Sick','Recovering','Recovered') THEN RAISE EXCEPTION 'Invalid health status'; END IF; IF greatest(length(new.details),length(new.medicine),length(new.treatment),length(new.recovery))>4000 THEN RAISE EXCEPTION 'Health details must be up to 4000 characters'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_health_before_insert BEFORE INSERT ON public.animal_health FOR EACH ROW EXECUTE FUNCTION public.validate_animal_health();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.customer_portal()'::regprocedure) INTO definition; definition:=replace(definition,'RETURN jsonb_build_object','IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=''customer'') THEN RAISE EXCEPTION ''Customer account required''; END IF; RETURN jsonb_build_object'); EXECUTE definition; END $$;